SELECT inquiry_id AS inquiryId, user_id AS userId, supplier_id AS supplierId,
product_id AS productId, quantity, content, status, created_at AS createdAt
FROM inquiry
WHERE supplier_id = #{supplierId}
AND status = #{status}
ORDER BY created_at DESC

